import React, { useCallback, Fragment } from 'react'
import PropTypes from 'prop-types'
import LayoutContentStyle from '../../../../../../components/utility/layoutContent'
import { PropertyImgsStyle } from './index.style'
import { Col, Row, Upload } from 'antd'
import ModalImage from 'react-modal-image'
import { BUILDING_IMG } from '../../constants'
import PermissionCheckerV2 from '../../../../../../components/permissionCheckerV2'
function PropertyImgs (props) {
  const renderImgContainer = useCallback((images = {}, propertyImgType) => {
    const imgs = []
    for (const key in images) {
      if (images[key]) {
        imgs.push(
          <Col className='img-container'>
            <ModalImage
              className='property-img'
              small={images[key]}
              large={images[key]}
              id={key}
              name={key}
              imageBackgroundColor='transparent'
            />
            <PermissionCheckerV2 requiredPermission='ops.view_agent_policy_reupload_documents_btn'>
              {
                props.isShowReuploadBtn && (
                  <Upload
                    name='file'
                    accept='.jpg,.png,.jpeg'
                    multiple={false}
                    showUploadList={false}
                    customRequest={({ file }) => props.onReupload({
                      key: `${propertyImgType}.${key}`,
                      file
                    })}
                    className='img-reupload-btn'
                  >
                    Reupload Document
                  </Upload>
                )
              }
            </PermissionCheckerV2>
          </Col>
        )
      }
    }
    return imgs
  }, [props.onReupload, props.isShowReuploadBtn])

  const renderImgs = useCallback(() => {
    return BUILDING_IMG.map(item => {
      return (
        <Fragment key={item}>
          <div className='property-img-title'>
            {item.replace(/_/g, ' ')}
          </div>
          <Row type='flex'>
            {
              renderImgContainer(props.policy && props.policy[item], item)
            }
          </Row>
        </Fragment>
      )
    })
  }, [props.policy])

  return (
    <LayoutContentStyle className='details-info-container policy-detail-card'>
      <h3 className='policy-title'>Insured Images</h3>
      <PropertyImgsStyle>
        {renderImgs()}
      </PropertyImgsStyle>
    </LayoutContentStyle>
  )
}

PropertyImgs.propTypes = {
  policy: PropTypes.object,
  isShowReuploadBtn: PropTypes.bool,
  onReupload: PropTypes.func
}

export default PropertyImgs
